import {
  act,
  cleanup,
  fireEvent,
  render,
  screen,
  waitFor,
} from "@testing-library/react";
import { MemoryRouter } from "react-router";
import { afterEach, beforeEach, expect, it, vi } from "vitest";
import {
  controlServer,
  stubConsoleBrowser,
  type ControlServer,
} from "../../test/controlKit";

// gaulatti/alcantara#194 group 2: on-air actions. Fade to black on the TV deck,
// and instants on the radio cartwall: a click or its keyboard shortcut plays
// one, it shows as playing for the clip's length, and Stop all ends them.

vi.mock("../hooks/useSSE", () => ({ useSSE: () => ({ isConnected: false }) }));
vi.mock("../utils/globalProgram", () => ({
  useGlobalProgramId: () => ["main"],
}));
vi.mock("../contexts/ConsolePreferencesContext", async (original) => {
  const actual =
    await original<typeof import("../contexts/ConsolePreferencesContext")>();
  return {
    ...actual,
    useConsolePreferences: () => ({
      profile: actual.defaultConsoleProfile("desktop"),
      updateProfile: vi.fn(),
    }),
  };
});

import Control from "./control";

let server: ControlServer;

// Clip lengths by URL; an unknown URL fails to load, as a broken clip does.
const clipSeconds: Record<string, number> = {
  "https://media.example.test/bell.mp3": 2,
  "https://media.example.test/silent.mp3": 0,
};
class FakeAudio {
  preload = "";
  src = "";
  duration = Number.NaN;
  onloadedmetadata: (() => void) | null = null;
  onerror: (() => void) | null = null;
  load() {
    const url = this.src;
    queueMicrotask(() => {
      if (url in clipSeconds) {
        this.duration = clipSeconds[url];
        this.onloadedmetadata?.();
      } else this.onerror?.();
    });
  }
}

const instants = [
  {
    id: 1,
    name: "Fictional bell",
    audioUrl: "https://media.example.test/bell.mp3",
    volume: 1,
    enabled: true,
    position: 0,
  },
  {
    id: 2,
    name: "Fictional sting",
    audioUrl: "https://media.example.test/broken.mp3",
    volume: 1,
    enabled: true,
    position: 1,
  },
  {
    id: 3,
    name: "Fictional silence",
    audioUrl: "https://media.example.test/silent.mp3",
    volume: 1,
    enabled: false,
    position: 2,
  },
];

function state(type: "radio" | "tv", fadeToBlack = false) {
  return {
    id: 1,
    programId: "main",
    type,
    activeSceneId: null,
    fadeToBlack,
    scenes: [],
    mediaGroups: [],
  };
}

function open(type: "radio" | "tv") {
  server = controlServer({
    "GET /scenes": Response.json([]),
    "GET /instants": Response.json(instants),
    "GET /songs?limit=0": Response.json([]),
    "GET /program/main/state": Response.json(state(type)),
    "GET /program/main/media-groups": Response.json([]),
  });
  render(
    <MemoryRouter>
      <Control />
    </MemoryRouter>,
  );
}

beforeEach(() => {
  vi.spyOn(console, "error").mockImplementation(() => {});
  vi.spyOn(console, "log").mockImplementation(() => {});
  stubConsoleBrowser();
  vi.stubGlobal("Audio", FakeAudio);
});

afterEach(() => {
  cleanup();
  vi.useRealTimers();
  vi.restoreAllMocks();
  vi.unstubAllGlobals();
});

it("fades the TV program to black after the operator confirms, and restores it", async () => {
  open("tv");
  server.answer(
    "PUT /program/main/fade-to-black",
    Response.json(state("tv", true)),
  );
  fireEvent.click(
    await screen.findByRole("button", { name: "ARM FADE TO BLACK" }),
  );
  fireEvent.click(
    screen.getByRole("button", { name: "CONFIRM FADE TO BLACK" }),
  );
  expect(
    await screen.findByRole("button", { name: "RESTORE PROGRAM" }),
  ).toBeVisible();
  expect(server.requests("PUT /program/main/fade-to-black")).toEqual([
    { active: true },
  ]);

  server.answer(
    "PUT /program/main/fade-to-black",
    Response.json(state("tv", false)),
  );
  fireEvent.click(screen.getByRole("button", { name: "RESTORE PROGRAM" }));
  expect(
    await screen.findByRole("button", { name: "ARM FADE TO BLACK" }),
  ).toBeVisible();
  expect(server.requests("PUT /program/main/fade-to-black")).toEqual([
    { active: true },
    { active: false },
  ]);
});

it("keeps the program as it was when fade to black is refused or answered with nothing usable", async () => {
  open("tv");
  server.answer(
    "PUT /program/main/fade-to-black",
    new Response("no", { status: 503 }),
  );
  fireEvent.click(
    await screen.findByRole("button", { name: "ARM FADE TO BLACK" }),
  );
  fireEvent.click(
    screen.getByRole("button", { name: "CONFIRM FADE TO BLACK" }),
  );
  await waitFor(() =>
    expect(server.requests("PUT /program/main/fade-to-black")).toHaveLength(1),
  );
  server.answer("PUT /program/main/fade-to-black", Response.json(null));
  fireEvent.click(
    await screen.findByRole("button", { name: "ARM FADE TO BLACK" }),
  );
  fireEvent.click(
    screen.getByRole("button", { name: "CONFIRM FADE TO BLACK" }),
  );
  await waitFor(() =>
    expect(server.requests("PUT /program/main/fade-to-black")).toHaveLength(2),
  );
  expect(
    screen.queryByRole("button", { name: "RESTORE PROGRAM" }),
  ).toBeNull();
});

it("plays an instant from the cartwall, shows it playing for the clip's length, and plays it again", async () => {
  open("radio");
  server.answer(
    "POST /instants/1/play?programId=main",
    Response.json({}),
  );
  const bell = await screen.findByRole("button", { name: "Fictional bell" });
  // Wait until the clip's length is known.
  await act(async () => {
    await Promise.resolve();
  });
  vi.useFakeTimers({ shouldAdvanceTime: true });
  fireEvent.click(bell);
  expect(
    await screen.findByRole("button", { name: "Fictional bell · playing" }),
  ).toBeVisible();
  // Played again while playing: one playing state, restarted.
  fireEvent.click(
    screen.getByRole("button", { name: "Fictional bell · playing" }),
  );
  await waitFor(() =>
    expect(
      server.requests("POST /instants/1/play?programId=main"),
    ).toHaveLength(2),
  );
  await act(async () => {
    vi.advanceTimersByTime(2100);
  });
  expect(
    await screen.findByRole("button", { name: "Fictional bell" }),
  ).toBeVisible();
});

it("plays an instant of unknown length until Stop all, and plays one from its keyboard shortcut", async () => {
  open("radio");
  server.answer("POST /instants/2/play?programId=main", Response.json({}));
  server.answer("POST /instants/1/play?programId=main", Response.json({}));
  server.answer("POST /instants/stop-all?programId=main", Response.json({}));
  fireEvent.click(await screen.findByRole("button", { name: "Fictional sting" }));
  expect(
    await screen.findByRole("button", { name: "Fictional sting · playing" }),
  ).toBeVisible();
  // Ctrl+Q plays the first instant.
  fireEvent.keyDown(window, { key: "q", code: "KeyQ", ctrlKey: true });
  await waitFor(() =>
    expect(
      server.requests("POST /instants/1/play?programId=main"),
    ).toHaveLength(1),
  );
  fireEvent.click(screen.getByRole("button", { name: "Stop all" }));
  await waitFor(() =>
    expect(
      screen.queryByRole("button", { name: /· playing$/ }),
    ).toBeNull(),
  );
  expect(
    server.requests("POST /instants/stop-all?programId=main"),
  ).toHaveLength(1);
});

it("ignores shortcuts for a disabled or missing instant, and keeps playing states when Stop all is refused", async () => {
  open("radio");
  server.answer("POST /instants/2/play?programId=main", Response.json({}));
  server.answer(
    "POST /instants/stop-all?programId=main",
    new Response("no", { status: 500 }),
  );
  server.answer(
    "POST /instants/1/play?programId=main",
    new Response("no", { status: 500 }),
  );
  await screen.findByRole("button", { name: "Fictional sting" });
  // Ctrl+E is the third (disabled) instant, Ctrl+R names none, Ctrl+1 is
  // not armed, a plain Q is not a shortcut, Ctrl+Shift+Q and Ctrl+5 are not
  // instant keys, and nothing typed in a field is a shortcut.
  fireEvent.keyDown(window, { key: "e", code: "KeyE", ctrlKey: true });
  fireEvent.keyDown(window, { key: "r", code: "KeyR", ctrlKey: true });
  fireEvent.keyDown(window, { key: "1", code: "Digit1", ctrlKey: true });
  fireEvent.keyDown(window, { key: "q", code: "KeyQ" });
  fireEvent.keyDown(window, {
    key: "Q",
    code: "KeyQ",
    ctrlKey: true,
    shiftKey: true,
  });
  fireEvent.keyDown(window, { key: "5", code: "Digit5", ctrlKey: true });
  // Armed, but this console has no scene 1 to prepare.
  fireEvent.keyDown(window, { key: "s", code: "KeyS", ctrlKey: true });
  fireEvent.keyDown(window, { key: "1", code: "Digit1", ctrlKey: true });
  fireEvent.keyDown(screen.getByRole("textbox", { name: "Search cartwall" }), {
    key: "q",
    code: "KeyQ",
    ctrlKey: true,
  });
  // A refused play shows nothing as playing.
  fireEvent.click(screen.getByRole("button", { name: "Fictional bell" }));
  await waitFor(() =>
    expect(
      server.requests("POST /instants/1/play?programId=main"),
    ).toHaveLength(1),
  );
  expect(
    screen.queryByRole("button", { name: "Fictional bell · playing" }),
  ).toBeNull();
  fireEvent.click(screen.getByRole("button", { name: "Fictional sting" }));
  await screen.findByRole("button", { name: "Fictional sting · playing" });
  fireEvent.click(screen.getByRole("button", { name: "Stop all" }));
  await waitFor(() =>
    expect(
      server.requests("POST /instants/stop-all?programId=main"),
    ).toHaveLength(1),
  );
  expect(
    screen.getByRole("button", { name: "Fictional sting · playing" }),
  ).toBeVisible();
  expect(
    server.calls.filter((call) => /instants\/3\/play/.test(call.path)),
  ).toEqual([]);
  expect(server.requests("POST /program/main/stage")).toEqual([]);
});

it("prepares a scene from Ctrl+S then its number, and only while armed", async () => {
  const scene = (id: number, name: string) => ({
    id,
    name,
    layoutId: 1,
    metadata: {},
    layout: { id: 1, name: "Fixture layout", componentType: "toni-clock" },
  });
  const first = scene(1, "Fictional headlines");
  const tenth = scene(10, "Fictional tenth");
  const assigned = Array.from({ length: 10 }, (_, index) => {
    const entry = index === 0 ? first : index === 9 ? tenth : scene(index + 1, `Fictional ${index + 1}`);
    return { id: index + 1, sceneId: entry.id, position: index, scene: entry };
  });
  server = controlServer({
    "GET /scenes": Response.json(assigned.map((entry) => entry.scene)),
    "GET /instants": Response.json([]),
    "GET /songs?limit=0": Response.json([]),
    "GET /program/main/state": Response.json({ ...state("tv"), scenes: assigned }),
    "GET /program/main/media-groups": Response.json([]),
    "POST /program/main/stage": Response.json({ stagedSceneId: 1, stagedScene: first }),
  });
  render(
    <MemoryRouter>
      <Control />
    </MemoryRouter>,
  );
  await screen.findAllByRole("button", { name: /Fictional headlines/ });
  fireEvent.keyDown(window, { key: "s", code: "KeyS", ctrlKey: true });
  fireEvent.keyDown(window, { key: "1", code: "Digit1", ctrlKey: true });
  await waitFor(() =>
    expect(server.requests("POST /program/main/stage")).toHaveLength(1),
  );
  // 0 is the tenth scene.
  server.answer("POST /program/main/stage", Response.json({ stagedSceneId: 10, stagedScene: tenth }));
  fireEvent.keyDown(window, { key: "s", code: "KeyS", ctrlKey: true });
  fireEvent.keyDown(window, { key: "0", code: "Digit0", ctrlKey: true });
  await waitFor(() =>
    expect(server.requests("POST /program/main/stage")).toHaveLength(2),
  );
  expect(server.requests("POST /program/main/stage")).toEqual([
    { sceneId: 1 },
    { sceneId: 10 },
  ]);
  // Used once: a second number without Ctrl+S prepares nothing.
  fireEvent.keyDown(window, { key: "2", code: "Digit2", ctrlKey: true });
  await act(async () => {
    await Promise.resolve();
  });
  expect(server.requests("POST /program/main/stage")).toHaveLength(2);
});

import {
  cleanup,
  fireEvent,
  render,
  screen,
  waitFor,
} from "@testing-library/react";
import { MemoryRouter } from "react-router";
import { afterEach, beforeEach, expect, it, vi } from "vitest";
import {
  controlServer,
  stubConsoleBrowser,
  type ControlServer,
} from "../../test/controlKit";

// gaulatti/alcantara#194 group 1: the radio song desk. Saving the filler
// rotation, taking a song on air, and the Play Next queue (add, move, remove)
// go to the program's audio bus and song queue; what the server answers is
// what the desk shows, and a refused request is shown and reloaded.

vi.mock("../hooks/useSSE", () => ({ useSSE: () => ({ isConnected: false }) }));
vi.mock("../utils/globalProgram", () => ({
  useGlobalProgramId: () => ["main"],
}));
vi.mock("../contexts/ConsolePreferencesContext", async (original) => {
  const actual =
    await original<typeof import("../contexts/ConsolePreferencesContext")>();
  return {
    ...actual,
    useConsolePreferences: () => ({
      profile: actual.defaultConsoleProfile("desktop"),
      updateProfile: vi.fn(),
    }),
  };
});

import Control from "./control";

let server: ControlServer;

const song = (id: string, title: string, songId: number) => ({
  id,
  kind: "preset",
  songId,
  artist: "Fictional artist",
  title,
  coverUrl: "https://media.example.test/cover.jpg",
  audioUrl: `https://media.example.test/${id}.mp3`,
  durationMs: 180_000,
});
const first = song("s1", "Fictional opener", 11);
const second = song("s2", "Fictional closer", 12);

const rotation = (mode: string, activeItemId: string | null = "s1") => ({
  mode,
  items: [first, second],
  activeItemId,
  intervalMs: 4000,
  loop: true,
  startedAt: Date.parse("2026-11-21T10:00:00Z"),
});
const queue = [
  { id: "q1", itemId: "s1", enqueuedAt: Date.parse("2026-11-21T10:00:00Z") },
  { id: "q2", itemId: "s2", enqueuedAt: Date.parse("2026-11-21T10:01:00Z") },
];

function open(
  mode = "manual",
  songQueue: unknown[] = queue,
  items: unknown[] = [first, second],
) {
  server = controlServer({
    "GET /scenes": Response.json([]),
    "GET /instants": Response.json([]),
    "GET /songs?limit=0": Response.json([]),
    "GET /program/main/state": Response.json({
      id: 1,
      programId: "main",
      type: "radio",
      activeSceneId: null,
      fadeToBlack: false,
      scenes: [],
      mediaGroups: [],
    }),
    "GET /program/main/media-groups": Response.json([]),
    "GET /program/main/audio-bus": () =>
      Response.json({
        version: 5,
        songSequence: { ...rotation(mode), items },
        songQueue,
      }),
  });
  render(
    <MemoryRouter>
      <Control />
    </MemoryRouter>,
  );
}

beforeEach(() => {
  vi.spyOn(console, "error").mockImplementation(() => {});
  vi.spyOn(console, "log").mockImplementation(() => {});
  stubConsoleBrowser();
});

afterEach(() => {
  cleanup();
  vi.restoreAllMocks();
  vi.unstubAllGlobals();
});

it("takes a song on air in manual rotation: saves the rotation, then sends the song to the radio", async () => {
  open("manual");
  server.answer(
    "PUT /program/main/audio-bus",
    Response.json({
      songSequence: rotation("manual", "s2"),
      songQueue: [queue[1]],
      mixerSettings: { songMasterVolume: 0.5 },
    }),
  );
  server.answer("POST /radio/main/song", Response.json({}));
  const takes = await screen.findAllByRole("button", { name: "Take on air" });
  fireEvent.click(takes[1]);
  await waitFor(() =>
    expect(server.requests("POST /radio/main/song")).toEqual([
      {
        audioUrl: second.audioUrl,
        title: second.title,
        artist: second.artist,
        coverUrl: second.coverUrl,
        durationMs: second.durationMs,
        songId: second.songId,
      },
    ]),
  );
  const [saved] = server.requests("PUT /program/main/audio-bus") as Array<{
    songSequence: { activeItemId: string; items: unknown[] };
  }>;
  expect(saved.songSequence.activeItemId).toBe("s2");
  expect(saved.songSequence.items).toHaveLength(2);
  // The queue the server answered replaces the shown one.
  await waitFor(() =>
    expect(
      screen.queryByRole("button", {
        name: "Remove Fictional opener from Play Next",
      }),
    ).toBeNull(),
  );
});

it("starts an idle automatic rotation by saving it alone, without a second manual take", async () => {
  open("autoplay");
  server.answer(
    "PUT /program/main/audio-bus",
    Response.json({ songSequence: rotation("autoplay", "s2") }),
  );
  fireEvent.click(
    (await screen.findAllByRole("button", { name: "Take on air" }))[1],
  );
  await waitFor(() =>
    expect(server.requests("PUT /program/main/audio-bus")).toHaveLength(1),
  );
  expect(server.requests("POST /radio/main/song")).toEqual([]);
});

it("shows a refused take and reloads the rotation from the server", async () => {
  open("manual");
  server.answer(
    "PUT /program/main/audio-bus",
    new Response("down", { status: 500 }),
  );
  const busReads = () =>
    server.calls.filter(
      (call) =>
        call.method === "GET" && call.path === "/program/main/audio-bus",
    ).length;
  const takes = await screen.findAllByRole("button", { name: "Take on air" });
  await waitFor(() => expect(busReads()).toBeGreaterThan(0));
  const before = busReads();
  fireEvent.click(takes[1]);
  expect(await screen.findByText("HTTP 500")).toBeVisible();
  // The rotation the server holds is read again.
  await waitFor(() => expect(busReads()).toBe(before + 1));
  expect(server.requests("POST /radio/main/song")).toEqual([]);
});

it("shows a song the radio refused after the rotation was saved", async () => {
  open("manual");
  server.answer(
    "PUT /program/main/audio-bus",
    Response.json({ songSequence: rotation("manual", "s2") }),
  );
  server.answer("POST /radio/main/song", new Response("no", { status: 502 }));
  fireEvent.click(
    (await screen.findAllByRole("button", { name: "Take on air" }))[1],
  );
  expect(await screen.findByText("HTTP 502")).toBeVisible();
});

it("moves and removes Play Next songs through the song queue and shows the queue the server answers", async () => {
  open("manual");
  server.answer(
    "PUT /program/main/song-queue",
    Response.json({ songQueue: [queue[1], queue[0]] }),
  );
  server.answer(
    "DELETE /program/main/song-queue/q2",
    Response.json({ songQueue: [queue[0]] }),
  );
  fireEvent.click(
    await screen.findByRole("button", { name: "Move Fictional closer earlier" }),
  );
  await waitFor(() =>
    expect(server.requests("PUT /program/main/song-queue")).toEqual([
      { entryIds: ["q2", "q1"] },
    ]),
  );
  fireEvent.click(
    await screen.findByRole("button", {
      name: "Remove Fictional closer from Play Next",
    }),
  );
  await waitFor(() =>
    expect(
      server.calls.filter(
        (call) => call.method === "DELETE",
      ).map((call) => call.path),
    ).toEqual(["/program/main/song-queue/q2"]),
  );
  await waitFor(() =>
    expect(
      screen.queryByRole("button", {
        name: "Remove Fictional closer from Play Next",
      }),
    ).toBeNull(),
  );
});

it("adds a song to Play Next through the song queue", async () => {
  open("manual", []);
  server.answer(
    "POST /program/main/song-queue",
    Response.json({ songQueue: [queue[1]] }),
  );
  fireEvent.click(
    await screen.findByRole("button", { name: "Play Fictional closer next" }),
  );
  await waitFor(() =>
    expect(server.requests("POST /program/main/song-queue")).toEqual([
      { itemId: "s2" },
    ]),
  );
  expect(
    await screen.findByRole("button", {
      name: "Remove Fictional closer from Play Next",
    }),
  ).toBeVisible();
});

it("ignores an answer older than what the desk already shows, and keeps its own rotation when the answer has none", async () => {
  open("manual");
  // An older audio bus answer (version 4 after 5) changes nothing shown.
  server.answer(
    "PUT /program/main/audio-bus",
    Response.json({ version: 4, songQueue: [] }),
  );
  server.answer("POST /radio/main/song", Response.json({}));
  fireEvent.click(
    (await screen.findAllByRole("button", { name: "Take on air" }))[1],
  );
  await waitFor(() =>
    expect(server.requests("POST /radio/main/song")).toHaveLength(1),
  );
  expect(
    screen.getByRole("button", { name: "Remove Fictional opener from Play Next" }),
  ).toBeVisible();

  // A newer answer without a rotation keeps the rotation the desk saved.
  server.answer("PUT /program/main/audio-bus", Response.json({ version: 6 }));
  fireEvent.click(
    (await screen.findAllByRole("button", { name: "Take on air" }))[0],
  );
  await waitFor(() =>
    expect(server.requests("POST /radio/main/song")).toHaveLength(2),
  );
  expect(server.requests("POST /radio/main/song")[1]).toMatchObject({
    title: first.title,
  });
});

it("saves a take of a song without audio but sends nothing to the radio", async () => {
  const silent = { ...second, audioUrl: undefined };
  open("manual", queue, [first, silent]);
  server.answer(
    "PUT /program/main/audio-bus",
    Response.json({ version: 6 }),
  );
  fireEvent.click(
    (await screen.findAllByRole("button", { name: "Take on air" }))[1],
  );
  await waitFor(() =>
    expect(server.requests("PUT /program/main/audio-bus")).toHaveLength(1),
  );
  expect(server.requests("POST /radio/main/song")).toEqual([]);
});

it("shows a refused Play Next change and ignores a queue answer that is empty or older", async () => {
  open("manual");
  server.answer(
    "PUT /program/main/song-queue",
    new Response("busy", { status: 409 }),
  );
  fireEvent.click(
    await screen.findByRole("button", { name: "Move Fictional closer earlier" }),
  );
  expect(
    await screen.findByText("The Play Next queue was not changed. Try again."),
  ).toBeVisible();

  server.answer(
    "DELETE /program/main/song-queue/q2",
    Response.json({ version: 4, songQueue: [] }),
  );
  fireEvent.click(
    screen.getByRole("button", { name: "Remove Fictional closer from Play Next" }),
  );
  await waitFor(() =>
    expect(server.calls.some((call) => call.method === "DELETE")).toBe(true),
  );
  server.answer("DELETE /program/main/song-queue/q1", Response.json(null));
  fireEvent.click(
    screen.getByRole("button", { name: "Remove Fictional opener from Play Next" }),
  );
  await waitFor(() =>
    expect(
      server.calls.filter((call) => call.method === "DELETE"),
    ).toHaveLength(2),
  );
  // Neither answer replaced the queue.
  expect(
    screen.getByRole("button", { name: "Remove Fictional opener from Play Next" }),
  ).toBeVisible();
  expect(
    screen.getByRole("button", { name: "Remove Fictional closer from Play Next" }),
  ).toBeVisible();
});

it("shows a refused removal", async () => {
  open("manual");
  server.answer(
    "DELETE /program/main/song-queue/q1",
