  const removeQueuedProgramSong = async (entryId: string) => {
    const targetProgramId = activeProgramId;
    const res = await authFetch(
      `/program/${encodeURIComponent(targetProgramId)}/song-queue/${encodeURIComponent(entryId)}`,
      { method: "DELETE" },
