/** A song sequence flattened to its songs: legacy nested blocks are inlined. */
type ProgramSongPlaylist = Omit<ProgramSongSequence, 'items'> & { items: ProgramSongSequenceLeafItem[] };

function flattenProgramSongItems(items: ProgramSongSequenceItem[]): ProgramSongSequenceLeafItem[] {
  const flat: ProgramSongSequenceLeafItem[] = [];
  for (const item of items) {
    if (item.kind === 'preset') {
      flat.push(item);
      continue;
    }
    flat.push(...flattenProgramSongItems(item.sequence.items));
  }
  return flat;
}

function normalizeProgramSongPlaylist(sequence: ProgramSongSequence): ProgramSongPlaylist {
  const playlistItems = flattenProgramSongItems(sequence.items);
  return {
    ...sequence,
    items: playlistItems,
    activeItemId:
      sequence.activeItemId === null
        ? null
        : sequence.activeItemId && playlistItems.some((i) => i.id === sequence.activeItemId)
          ? sequence.activeItemId
          : (playlistItems[0]?.id ?? null)
  };
}

export function ProgramSongSequenceEditor({
  sequence: _sequence,
  songCatalog = [],
  programSongPlayback = null,
  onChange,
  onTakeSelection,
  onQueueItem,
  depth = 0,
  view = 'full',
  rotationLabel = 'Playlist'
}: {
  sequence: ProgramSongSequence;
  songCatalog?: SongCatalogItem[];
  programSongPlayback?: ProgramSongPlaybackState | null;
  onChange: (nextSequence: ProgramSongSequence) => void;
  onTakeSelection?: (nextSequence: ProgramSongSequence) => Promise<void> | void;
  onQueueItem?: (itemId: string) => Promise<void> | void;
  depth?: number;
  view?: 'full' | 'catalog' | 'queue';
  rotationLabel?: string;
}) {
  // Every item the editor shows is a song: the playlist type proves it.
  const sequence = useMemo(
    () => normalizeProgramSongPlaylist(normalizeProgramSongSequence(_sequence) ?? { ...createProgramSongSequence('manual'), activeItemId: null }),
    [_sequence]
  );

  const [draggingIndex, setDraggingIndex] = useState<number | null>(null);
  const [expandedItemId, setExpandedItemId] = useState<string | null>(null);
  const [addSongValue, setAddSongValue] = useState('');
  const [previewingItemId, setPreviewingItemId] = useState<string | null>(null);
  const previewAudioRef = useRef<HTMLAudioElement | null>(null);
  const isNested = depth > 0;
  const showQueue = view !== 'catalog';
  const showCatalog = view !== 'queue';
  const showQueueHeading = view === 'full' || rotationLabel !== 'Playlist';
  const isAutomatic = sequence.mode === 'autoplay' || sequence.mode === 'shuffle';
  const highRotationCount = useMemo(
    () => sequence.items.filter((item) => item.highRotation).length,
    [sequence.items]
  );

  const editorActiveItemId = useMemo(() => {
    if (programSongPlayback?.isPlaying) {
      const playbackItem = sequence.items.find((item) => programSongPlayback.token?.startsWith(`${item.id}:`));
      if (playbackItem) return playbackItem.id;
      const byUrl = sequence.items.filter((item) => item.audioUrl === programSongPlayback.audioUrl);
      return byUrl.length === 1 ? byUrl[0].id : null;
    }
    return sequence.activeItemId ?? (isAutomatic ? getProgramSongSequenceSelectedItemId(sequence, Date.now()) : null) ?? null;
  }, [isAutomatic, programSongPlayback?.isPlaying, programSongPlayback?.token, programSongPlayback?.audioUrl, sequence]);

  const availableSongCatalog = useMemo(
    () =>
      songCatalog
        .filter((s) => s.enabled && typeof s.audioUrl === 'string' && s.audioUrl.trim().length > 0)
        .sort((a, b) =>
          [a.artist, a.title].filter(Boolean).join(' - ').toLowerCase().localeCompare([b.artist, b.title].filter(Boolean).join(' - ').toLowerCase())
        ),
    [songCatalog]
  );

  const catalogOptions = useMemo(
    () => availableSongCatalog.map((s) => ({ value: String(s.id), label: [s.artist, s.title].filter(Boolean).join(' - ') || `Song #${s.id}` })),
    [availableSongCatalog]
  );

  useEffect(() => {
    if (expandedItemId && !sequence.items.some((i) => i.id === expandedItemId)) setExpandedItemId(null);
  }, [sequence.items, expandedItemId]);

  useEffect(() => {
    return () => {
      previewAudioRef.current?.pause();
      previewAudioRef.current = null;
    };
  }, []);

  const applySequence = useCallback(
    (nextSequence: ProgramSongSequence) => onChange(nextSequence),
    [onChange]
  );

  const previewItem = useCallback(async (item: ProgramSongSequenceLeafItem) => {
    const audioUrl = item.audioUrl?.trim() ?? '';
    if (!audioUrl) return;

    if (previewingItemId === item.id) {
      previewAudioRef.current?.pause();
      previewAudioRef.current = null;
      setPreviewingItemId(null);
      return;
    }

    previewAudioRef.current?.pause();
    const audio = new Audio(audioUrl);
    previewAudioRef.current = audio;
    audio.onended = () => {
      if (previewAudioRef.current === audio) {
        previewAudioRef.current = null;
        setPreviewingItemId(null);
      }
    };
    audio.onerror = () => {
      if (previewAudioRef.current === audio) {
        previewAudioRef.current = null;
        setPreviewingItemId(null);
      }
    };

    try {
      await audio.play();
      if (previewAudioRef.current === audio) setPreviewingItemId(item.id);
    } catch (error) {
      if (previewAudioRef.current === audio) {
        previewAudioRef.current = null;
        setPreviewingItemId(null);
      }
      console.error('Failed to play local song preview:', error);
    }
  }, [previewingItemId]);

  const resolveAutoplayStartedAt = useCallback((): number => {
    const now = Date.now();
    if (!programSongPlayback) return now;
    const targetId = editorActiveItemId ?? sequence.activeItemId;
    if (!targetId) return now;
    const target = sequence.items.find((i) => i.id === targetId);
    if (!target) return now;
    const itemUrl = target.audioUrl?.trim() || '';
    const pbUrl = programSongPlayback.audioUrl?.trim() || '';
    const pbToken = programSongPlayback.token || '';
    const matches = (itemUrl && pbUrl && itemUrl === pbUrl) || (target.id && pbToken.startsWith(`${target.id}:`));
    if (!matches) return now;
    return now - Math.max(0, Math.round(programSongPlayback.currentTimeMs));
  }, [editorActiveItemId, programSongPlayback, sequence.activeItemId, sequence.items]);

  const addItemFromCatalog = useCallback(
    (songId: number) => {
      const selectedSong = availableSongCatalog.find((s) => s.id === songId);
      if (!selectedSong) return;
      const nextItem = createProgramSongSequenceItem('preset');
      if (nextItem.kind !== 'preset') return;
      const filled = {
        ...nextItem,
        songId: selectedSong.id,
        artist: selectedSong.artist || '',
        title: selectedSong.title || '',
        coverUrl: selectedSong.coverUrl || '',
        audioUrl: selectedSong.audioUrl || '',
        durationMs:
          typeof selectedSong.durationMs === 'number' && Number.isFinite(selectedSong.durationMs) && selectedSong.durationMs > 0
            ? Math.round(selectedSong.durationMs)
            : nextItem.durationMs,
        earoneSongId: selectedSong.earoneSongId || nextItem.earoneSongId,
        earoneRank: selectedSong.earoneRank || nextItem.earoneRank,
        earoneSpins: selectedSong.earoneSpins || nextItem.earoneSpins
      };
      applySequence({
        ...sequence,
        items: [...sequence.items, filled],
        activeItemId: isAutomatic ? (editorActiveItemId ?? sequence.activeItemId ?? filled.id) : editorActiveItemId
      });
    },
    [applySequence, availableSongCatalog, editorActiveItemId, isAutomatic, sequence]
  );

  const removeItem = useCallback(
    (index: number) => {
      const removed = sequence.items[index];
      if (!removed) return;
      const nextItems = sequence.items.filter((_, i) => i !== index);
      const current = editorActiveItemId ?? sequence.activeItemId;
      const removedCurrent = current !== null && current === removed.id;
      let nextActive: string | null;
      if (nextItems.length === 0) nextActive = null;
      else if (removedCurrent) nextActive = nextItems[Math.min(index, nextItems.length - 1)]?.id ?? null;
      else nextActive = current && nextItems.some((i) => i.id === current) ? current : (nextItems[0]?.id ?? null);
      applySequence({
        ...sequence,
        items: nextItems,
        activeItemId: nextActive,
        startedAt: isAutomatic && !removedCurrent ? resolveAutoplayStartedAt() : Date.now()
      });
    },
    [applySequence, editorActiveItemId, isAutomatic, resolveAutoplayStartedAt, sequence]
  );

  const updateItem = useCallback(
    (index: number, updatedItem: ProgramSongSequenceLeafItem) => {
      const nextItems = sequence.items.map((item, i) => (i === index ? updatedItem : item));
      applySequence({ ...sequence, items: nextItems });
    },
    [applySequence, sequence]
  );

  const toggleHighRotation = useCallback(
    (index: number, item: ProgramSongSequenceLeafItem) => {
      if (!item.highRotation && highRotationCount >= 12) return;
      updateItem(index, { ...item, highRotation: !item.highRotation });
    },
    [highRotationCount, updateItem]
  );

  const reorderItems = useCallback(
    (fromIndex: number, toIndex: number) => {
      if (fromIndex === toIndex || fromIndex < 0 || toIndex < 0 || fromIndex >= sequence.items.length || toIndex >= sequence.items.length) return;
      const next = [...sequence.items];
      const [moved] = next.splice(fromIndex, 1);
      next.splice(toIndex, 0, moved);
      applySequence({ ...sequence, items: next });
    },
    [applySequence, sequence]
  );

  const applyCatalogSongToItem = useCallback(
    (index: number, item: ProgramSongSequenceLeafItem, song: SongCatalogItem) => {
      updateItem(index, {
        ...item,
        songId: song.id,
        artist: song.artist || item.artist,
        title: song.title || item.title,
        coverUrl: song.coverUrl || item.coverUrl,
        audioUrl: song.audioUrl || item.audioUrl,
        durationMs:
          typeof song.durationMs === 'number' && Number.isFinite(song.durationMs) && song.durationMs > 0 ? Math.round(song.durationMs) : item.durationMs,
        earoneSongId: song.earoneSongId || item.earoneSongId,
        earoneRank: song.earoneRank || item.earoneRank,
        earoneSpins: song.earoneSpins || item.earoneSpins
      });
    },
    [updateItem]
  );

  function formatDurationFromMs(ms: number | null | undefined) {
    if (typeof ms !== 'number' || !Number.isFinite(ms) || ms <= 0) return '—';
    const totalSec = Math.round(ms / 1000);
    return `${Math.floor(totalSec / 60)}:${String(totalSec % 60).padStart(2, '0')}`;
  }

  return (
    <div className={`flex flex-col overflow-hidden rounded-xl ${isNested ? 'border border-sand/30 bg-dark-sand/70' : 'h-full min-h-0 bg-dark-sand'}`}>
      <div className='flex min-h-0 flex-1 flex-col md:flex-row'>
        {showQueue ? (
          <div className={`flex min-h-0 flex-1 flex-col ${showCatalog ? 'border-r-0 border-sand/30 md:border-r' : ''}`}>
            {showQueueHeading ? (
              <div className='flex items-center justify-between border-b border-sand/30 bg-dark-sand/70 px-4 py-2 border-t border-sand/20'>
                <span className='text-[10px] font-semibold uppercase tracking-widest text-text-secondary'>{rotationLabel}</span>
                <span className='text-[10px] text-text-secondary'>
                  {sequence.items.length} {sequence.items.length === 1 ? 'song' : 'songs'}
                </span>
              </div>
            ) : null}
            {sequence.items.length === 0 ? (
              <div className='flex flex-1 flex-col items-center justify-center px-4 py-16 text-center'>
                <Music2 size={32} className='mb-3 text-text-secondary' />
                <p className='text-sm font-medium text-text-primary'>{rotationLabel} is empty</p>
                <p className='mt-1 text-xs text-text-secondary'>{rotationLabel === 'Playlist' ? 'Search and add songs from the catalog panel.' : 'Use Add fillers to choose Library songs.'}</p>
              </div>
            ) : (
              <div className='min-h-0 flex-1 overflow-auto'>
                <div className='playlist-table min-w-100'>
                  <div className='playlist-column-heading grid grid-cols-[28px_28px_28px_28px_1fr_52px_84px] items-center border-b border-sand/30 px-3 py-1.5 text-[10px] font-medium uppercase tracking-widest text-text-secondary'>
                    <span />
                    <span className='text-center'>#</span>
                    <span />
                    <span className='text-center' title='High rotation favorites'>
                      ★
                    </span>
                    <span style={{ paddingLeft: '22px' }}>Title · High rotation {highRotationCount}/12</span>
                    <span className='flex items-center justify-end pr-3'>
                      <Clock size={10} />
                    </span>
                    <span />
                  </div>
                  <div className='divide-y divide-sand/20'>
                    {sequence.items.map((item, index) => {
                      const displayItem = item;
                      const isActive = displayItem.id === editorActiveItemId;
                      const isExpanded = expandedItemId === displayItem.id;
                      const selectedCatalogSong = availableSongCatalog.find((song) => {
                        if (displayItem.songId === song.id) return true;
                        if (displayItem.audioUrl && song.audioUrl === displayItem.audioUrl) return true;
                        return (
                          (song.artist || '').trim() === displayItem.artist.trim() &&
                          (song.title || '').trim() === displayItem.title.trim() &&
                          (song.coverUrl || '').trim() === displayItem.coverUrl.trim()
                        );
                      });
                      const selectedCatalogSongValue = selectedCatalogSong ? String(selectedCatalogSong.id) : '';
                      const titleText = displayItem.title.trim();
                      const artistText = displayItem.artist.trim();
                      const rowDuration = formatDurationFromMs(displayItem.durationMs);
                      const coverUrl = displayItem.coverUrl.trim();

                      return (
                        <div
                          key={displayItem.id}
                          onDragOver={(e) => e.preventDefault()}
                          onDrop={(e) => {
                            e.preventDefault();
                            if (draggingIndex !== null) reorderItems(draggingIndex, index);
                            setDraggingIndex(null);
                          }}
                        >
                          <div
                            data-active={isActive}
                            className={`playlist-row group grid grid-cols-[28px_28px_28px_28px_1fr_52px_84px] items-center px-3 py-1.5 transition-colors ${isActive ? 'bg-sea/15' : 'hover:bg-dark-sand/70'}`}
                          >
                            <span
                              draggable
                              onDragStart={() => setDraggingIndex(index)}
                              onDragEnd={() => setDraggingIndex(null)}
                              className='inline-flex h-6 w-6 cursor-grab select-none items-center justify-center text-text-secondary opacity-0 transition-opacity group-hover:opacity-100'
                              title='Drag to reorder'
                              aria-label='Drag to reorder'
                            >
                              <GripVertical size={12} strokeWidth={2} />
                            </span>
                            <Button
                              type='button'
                              onClick={() => {
                                const next = { ...sequence, activeItemId: displayItem.id, startedAt: Date.now() };
                                if (onTakeSelection) void onTakeSelection(next);
                                else applySequence(next);
                              }}
                              className='relative flex h-6 w-6 shrink-0 items-center justify-center border-0 bg-transparent p-0 shadow-none hover:translate-y-0 hover:scale-100 hover:bg-transparent'
                              title='Take on air'
                              aria-label='Take on air'
                            >
                              <span
                                className={`text-xs tabular-nums transition-opacity ${isActive ? 'opacity-0' : 'text-text-secondary group-hover:opacity-0'}`}
                              >
                                {index + 1}
                              </span>
                              {isActive && (
                                <span className='absolute inset-0 flex items-end justify-center gap-0.5 pb-0.5 group-hover:opacity-0'>
                                  <span className='w-0.75 rounded-sm bg-sea opacity-100' style={{ animation: 'eq-bar1 0.8s ease-in-out infinite alternate' }} />
                                  <span
                                    className='w-0.75 rounded-sm bg-sea opacity-100'
                                    style={{ animation: 'eq-bar2 0.8s ease-in-out 0.15s infinite alternate' }}
                                  />
                                  <span
                                    className='w-0.75 rounded-sm bg-sea opacity-100'
                                    style={{ animation: 'eq-bar1 0.8s ease-in-out 0.3s infinite alternate' }}
                                  />
                                </span>
                              )}
                              <span className='absolute inset-0 flex items-center justify-center opacity-0 transition-opacity group-hover:opacity-100'>
                                <PlayIcon />
                              </span>
                            </Button>
                            <Button
                              type='button'
                              onClick={() => void previewItem(displayItem)}
                              disabled={!displayItem.audioUrl?.trim()}
                              className={`flex h-6 w-6 shrink-0 items-center justify-center border-0 bg-transparent p-0 shadow-none hover:translate-y-0 hover:scale-100 hover:bg-transparent ${previewingItemId === displayItem.id ? 'text-sea' : 'text-text-secondary hover:text-text-primary'}`}
                              title={previewingItemId === displayItem.id ? 'Stop local preview' : 'Preview locally'}
                              aria-label={previewingItemId === displayItem.id ? 'Stop local preview' : 'Preview locally'}
                            >
                              <Headphones size={13} />
                            </Button>
                            <Button
                              type='button'
                              onClick={() => toggleHighRotation(index, displayItem)}
                              disabled={!displayItem.highRotation && highRotationCount >= 12}
                              className={`flex h-6 w-6 shrink-0 items-center justify-center border-0 bg-transparent p-0 shadow-none transition-colors hover:translate-y-0 hover:scale-100 hover:bg-transparent ${displayItem.highRotation ? 'text-amber-300' : 'text-text-secondary opacity-0 group-hover:opacity-100'} disabled:cursor-not-allowed disabled:opacity-30`}
                              title={
                                displayItem.highRotation
                                  ? 'Remove from high rotation'
                                  : highRotationCount >= 12
                                    ? 'High rotation is limited to 12 songs'
                                    : 'Add to high rotation'
                              }
                              aria-label={`${displayItem.highRotation ? 'Remove' : 'Add'} ${titleText || 'song'} ${displayItem.highRotation ? 'from' : 'to'} high rotation`}
                            >
                              <Star size={13} fill={displayItem.highRotation ? 'currentColor' : 'none'} />
                            </Button>
                            <div className='flex min-w-0 items-center gap-2.5 pl-1'>
                              {coverUrl ? (
                                <img src={coverUrl} alt={`${artistText} - ${titleText}`} className='h-9 w-9 shrink-0 rounded-sm object-cover shadow-md' />
                              ) : (
                                <div className='flex h-9 w-9 shrink-0 items-center justify-center rounded-sm bg-dark-sand text-xs font-bold text-text-secondary'>
                                  {titleText.slice(0, 1).toUpperCase() || '?'}
                                </div>
                              )}
                              <div className='min-w-0'>
                                <div className={`truncate text-[13px] font-medium leading-tight ${isActive ? 'text-sea' : 'text-text-primary'}`}>
                                  {titleText}
                                </div>
                                <div className='truncate text-[11px] leading-tight text-text-secondary mt-0.5'>{artistText}</div>
                              </div>
                            </div>
                            <span className={`text-right pr-3 text-xs tabular-nums ${isActive ? 'text-sea' : 'text-text-secondary'}`}>{rowDuration}</span>
                            <div className='playlist-row-actions flex items-center justify-end gap-1 opacity-0 transition-opacity group-hover:opacity-100'>
                              {onQueueItem ? (
                                <Button
                                  type='button'
                                  onClick={() => void onQueueItem(displayItem.id)}
                                  className='flex h-6 w-6 items-center justify-center rounded border-0 bg-transparent p-0 text-text-secondary shadow-none transition-colors hover:translate-y-0 hover:scale-100 hover:text-sea'
                                  title='Play next'
                                  aria-label={`Play ${titleText || 'song'} next`}
                                >
                                  <ListPlus size={13} />
                                </Button>
                              ) : null}
                              <Button
                                type='button'
                                onClick={() => setExpandedItemId((prev) => (prev === displayItem.id ? null : displayItem.id))}
                                className='flex h-6 w-6 items-center justify-center rounded border-0 bg-transparent p-0 text-text-secondary shadow-none transition-colors hover:translate-y-0 hover:scale-100 hover:text-text-primary'
                                title='Edit song'
                                aria-label='Edit song'
                              >
                                <svg
                                  width='13'
                                  height='13'
                                  viewBox='0 0 24 24'
                                  fill='none'
                                  stroke='currentColor'
                                  strokeWidth='2'
                                  strokeLinecap='round'
                                  strokeLinejoin='round'
                                >
                                  <path d='M12 20h9' />
                                  <path d='M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4 12.5-12.5z' />
                                </svg>
                              </Button>
                              <Button
                                type='button'
                                onClick={() => removeItem(index)}
                                className='flex h-6 w-6 items-center justify-center rounded border-0 bg-transparent p-0 text-text-secondary shadow-none transition-colors hover:translate-y-0 hover:scale-100 hover:text-terracotta'
                                title='Remove'
                                aria-label='Remove'
                              >
                                <svg
                                  width='13'
                                  height='13'
                                  viewBox='0 0 24 24'
                                  fill='none'
                                  stroke='currentColor'
                                  strokeWidth='2'
                                  strokeLinecap='round'
                                  strokeLinejoin='round'
                                >
                                  <polyline points='3 6 5 6 21 6' />
                                  <path d='M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6' />
                                  <path d='M10 11v6' />
                                  <path d='M14 11v6' />
                                  <path d='M9 6V4h6v2' />
                                </svg>
                              </Button>
                            </div>
                          </div>
                          {isExpanded ? (
                            <div className='border-t border-sand/30 bg-dark-sand/60 px-3 py-2'>
                              <div className='flex items-center rounded'>
                                <Select
                                  value={selectedCatalogSongValue}
                                  options={catalogOptions}
                                  placeholder='Swap song...'
                                  onChange={(v) => {
                                    const id = Number(v);
                                    if (Number.isFinite(id) && id > 0) {
                                      const song = availableSongCatalog.find((s) => s.id === id);
                                      if (song) {
                                        applyCatalogSongToItem(index, displayItem, song);
                                        setExpandedItemId(null);
                                      }
                                    }
                                  }}
                                />
                              </div>
                            </div>
                          ) : null}
                        </div>
                      );
                    })}
                  </div>
                </div>
              </div>
            )}
          </div>
        ) : null}

        {showCatalog ? (
          <div
            className={`flex min-h-0 flex-col border-t border-sand/30 bg-dark-sand/70 ${showQueue ? 'hidden w-[320px] shrink-0 md:flex' : 'min-h-0 flex-1'}`}
          >
            <div className='border-b border-sand/30 bg-dark-sand/80 p-2'>
              <Input
                type='text'
                placeholder='Search catalog to add...'
                value={addSongValue}
                onChange={(e) => setAddSongValue(e.target.value)}
                className='w-full rounded-md border border-sand/30 bg-dark-sand px-3 py-1.5 text-xs text-text-primary placeholder:text-text-secondary focus:border-sea/60 focus:outline-none focus:ring-1 focus:ring-sea/40'
              />
            </div>
            <div className={showQueue ? 'min-h-0 flex-1 overflow-y-auto' : 'max-h-125 overflow-y-auto'}>
              {availableSongCatalog
                .filter((s) => {
                  if (!addSongValue) return true;
                  const q = addSongValue.toLowerCase();
                  return s.title?.toLowerCase().includes(q) || s.artist?.toLowerCase().includes(q);
                })
                .slice(0, 80)
                .map((song) => (
                  <div key={song.id} className='group flex items-center justify-between border-b border-sand/20 px-3 py-2 hover:bg-dark-sand/70'>
                    <div className='flex min-w-0 items-center gap-2'>
                      {song.coverUrl ? (
                        <img src={song.coverUrl} alt='' className='h-8 w-8 shrink-0 rounded-sm object-cover opacity-80' />
                      ) : (
                        <div className='flex h-8 w-8 shrink-0 items-center justify-center rounded-sm bg-dark-sand text-text-secondary'>
                          {song.title?.charAt(0) || <Music2 size={12} />}
                        </div>
                      )}
                      <div className='min-w-0 pr-2'>
                        <div className='truncate text-[11px] font-medium text-text-primary'>{song.title}</div>
                        <div className='truncate text-[10px] text-text-secondary'>{song.artist}</div>
                      </div>
                    </div>
                    <Button
                      type='button'
                      onClick={() => addItemFromCatalog(song.id)}
                      className='flex h-6 w-6 shrink-0 items-center justify-center rounded-full border-0 bg-transparent p-0 text-text-secondary opacity-0 shadow-none transition-all hover:translate-y-0 hover:scale-100 hover:bg-sea/20 hover:text-sea group-hover:opacity-100'
                      title='Add to queue'
                      aria-label='Add to queue'
                    >
                      <Plus size={14} />
                    </Button>
                  </div>
                ))}
              {availableSongCatalog.length > 0 &&
                availableSongCatalog.filter(
                  (s) =>
                    !addSongValue || s.title?.toLowerCase().includes(addSongValue.toLowerCase()) || s.artist?.toLowerCase().includes(addSongValue.toLowerCase())
                ).length === 0 && <div className='p-4 text-center text-xs text-text-secondary'>No matches found</div>}
            </div>
          </div>
        ) : null}
      </div>
    </div>
  );
}

function PlayIcon() {
  return (
    <svg width='11' height='11' viewBox='0 0 24 24' fill='currentColor' className='text-text-primary'>
      <polygon points='5 3 19 12 5 21 5 3' />
    </svg>
  );
}

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Button, IconButton } from "@gaulatti/bleecker";
import {
  Music2,
  Play,
  Repeat2,
  Shuffle,
  SkipBack,
  SkipForward,
  Square,
  ZapOff,
} from "lucide-react";
import {
  createProgramSongSequence,
  getProgramSongSequenceSelectedItemId,
  normalizeProgramSongSequence,
  shuffleProgramSongSequence,
  type ProgramSongSequence,
} from "../utils/programSequence";
import type { ProgramSongPlaybackState } from "../models/broadcast";

function flattenProgramSongItems(
  items: ProgramSongSequence["items"],
): Extract<ProgramSongSequence["items"][number], { kind: "preset" }>[] {
  const flat: Extract<
    ProgramSongSequence["items"][number],
    { kind: "preset" }
  >[] = [];
  for (const item of items) {
    if (item.kind === "preset") {
      flat.push(item);
      continue;
    }
    flat.push(...flattenProgramSongItems(item.sequence.items));
  }
  return flat;
}

function normalizeProgramSongPlaylist(
  sequence: ProgramSongSequence,
): ProgramSongSequence {
  const playlistItems = flattenProgramSongItems(sequence.items);
  return {
    ...sequence,
    items: playlistItems,
    activeItemId:
      sequence.activeItemId === null
        ? null
        : sequence.activeItemId &&
            playlistItems.some((i) => i.id === sequence.activeItemId)
          ? sequence.activeItemId
          : (playlistItems[0]?.id ?? null),
  };
}

interface PlaybackBarProps {
  logTransport?: {
    isRunning: boolean;
    canStart: boolean;
    canAdvance: boolean;
    busy: boolean;
    label: string;
    onStart: () => void;
    onStop: () => void;
    onAdvance: () => void;
  };
  sequence: ProgramSongSequence;
  programSongPlayback: ProgramSongPlaybackState | null;
  onChange: (nextSequence: ProgramSongSequence) => void;
  onTakeSelection?: (nextSequence: ProgramSongSequence) => Promise<void> | void;
  onTakeOffAir?: () => Promise<void> | void;
  onStopAllInstants?: () => void;
}

export function PlaybackBar({
  sequence: _sequence,
  logTransport,
  programSongPlayback = null,
  onChange,
  onTakeSelection,
  onTakeOffAir,
  onStopAllInstants,
}: PlaybackBarProps) {
  const sequence = useMemo(() => {
    const n = normalizeProgramSongSequence(_sequence);
    return n
      ? normalizeProgramSongPlaylist(n)
      : { ...createProgramSongSequence("manual"), activeItemId: null };
  }, [_sequence]);

  const [nowMs, setNowMs] = useState(() => Date.now());
  const [stickyPlaybackItemId, setStickyPlaybackItemId] = useState<
    string | null
  >(null);
  const sequenceRef = useRef(sequence);
  const effectiveActiveItemId = getProgramSongSequenceSelectedItemId(
    sequence,
    nowMs,
  );
  const automaticPlayback =
    sequence.mode === "autoplay" || sequence.mode === "shuffle";

  const applySequence = useCallback(
    (nextSequence: ProgramSongSequence) => {
      onChange(nextSequence);
    },
    [onChange],
  );

  const playbackActiveItemId = useMemo(() => {
    if (!programSongPlayback?.isPlaying) return null;
    const token = (programSongPlayback.token || "").trim();
    const url = (programSongPlayback.audioUrl || "").trim();
    if (token) {
      const m = sequence.items.find(
        (i) => i.id && token.startsWith(`${i.id}:`),
      );
      if (m) return m.id;
    }
    if (url) {
      const matches = sequence.items.filter(
        (i) => i.kind === "preset" && (i.audioUrl || "").trim() === url,
      );
      if (matches.length === 1) return matches[0].id;
      if (matches.length > 1) {
        if (
          sequence.activeItemId &&
          matches.some((i) => i.id === sequence.activeItemId)
        )
          return sequence.activeItemId;
        if (
          effectiveActiveItemId &&
          matches.some((i) => i.id === effectiveActiveItemId)
        )
          return effectiveActiveItemId;
      }
    }
    return null;
  }, [effectiveActiveItemId, programSongPlayback, sequence]);

  useEffect(() => {
    if (programSongPlayback?.isPlaying) {
      if (
        playbackActiveItemId &&
        sequence.items.some((i) => i.id === playbackActiveItemId)
      ) {
        if (stickyPlaybackItemId !== playbackActiveItemId)
          setStickyPlaybackItemId(playbackActiveItemId);
        return;
      }
      if (
        stickyPlaybackItemId &&
        !sequence.items.some((i) => i.id === stickyPlaybackItemId)
      )
        setStickyPlaybackItemId(null);
      return;
    }
    if (stickyPlaybackItemId !== null) setStickyPlaybackItemId(null);
  }, [
    playbackActiveItemId,
    programSongPlayback?.isPlaying,
    sequence.items,
    stickyPlaybackItemId,
  ]);

  const runtimeActiveItemId = useMemo(() => {
    if (programSongPlayback?.isPlaying) {
      return (
        stickyPlaybackItemId ??
        playbackActiveItemId ??
        sequence.activeItemId ??
        (automaticPlayback ? effectiveActiveItemId : null) ??
        null
      );
    }
    return (
      sequence.activeItemId ??
      (automaticPlayback ? effectiveActiveItemId : null) ??
      null
    );
  }, [
    automaticPlayback,
    effectiveActiveItemId,
    playbackActiveItemId,
    programSongPlayback?.isPlaying,
    sequence.activeItemId,
    stickyPlaybackItemId,
  ]);

  const runtimeActiveItemIndex = runtimeActiveItemId
    ? sequence.items.findIndex((i) => i.id === runtimeActiveItemId)
    : -1;

  useEffect(() => {
    sequenceRef.current = sequence;
  }, [sequence]);

  useEffect(() => {
    if (!programSongPlayback?.isPlaying) return;
    const timer = setInterval(() => setNowMs(Date.now()), 250);
    return () => clearInterval(timer);
  }, [programSongPlayback?.isPlaying]);

  const clearActiveItem = useCallback(async () => {
    const next = { ...sequence, mode: "manual" as const, activeItemId: null };
    if (onTakeOffAir) {
      await onTakeOffAir();
      return;
    }
    if (onTakeSelection) await onTakeSelection(next);
    else applySequence(next);
  }, [applySequence, onTakeOffAir, onTakeSelection, sequence]);

  const activateItem = useCallback(
    async (itemId: string) => {
      const next = { ...sequence, activeItemId: itemId, startedAt: Date.now() };
      if (onTakeSelection) await onTakeSelection(next);
      else applySequence(next);
    },
    [applySequence, onTakeSelection, sequence],
  );

  return (
    <div className="playback-dock shrink-0 bg-dark-sand/95 shadow-[0_-10px_28px_rgba(0,0,0,0.45)] backdrop-blur supports-[backdrop-filter]:bg-dark-sand/90">
      <div className="playback-bar flex flex-wrap items-center justify-between gap-2 border-t border-sand/30 bg-dark-sand/85 px-3 py-2 sm:px-4 sm:py-3 md:flex-nowrap">
        <div className="order-2 flex items-center gap-2 md:order-none">
          {logTransport ? (
            <>
              <Button
                type="button"
                onClick={logTransport.onStart}
                disabled={!logTransport.canStart || logTransport.busy}
                aria-label="Start rundown"
              >
                <Play size={17} fill="currentColor" /> Start rundown
              </Button>
              <IconButton
                type="button"
                title="Stop rundown / Take Off Air"
                aria-label="Stop rundown / Take Off Air"
                onClick={logTransport.onStop}
                disabled={logTransport.busy}
              >
                <Square size={16} fill="currentColor" />
              </IconButton>
              <Button
                type="button"
                variant="secondary"
                onClick={logTransport.onAdvance}
                disabled={!logTransport.canAdvance || logTransport.busy}
                aria-label="Advance rundown"
              >
                <SkipForward size={16} /> Advance
              </Button>
            </>
          ) : (
            <>
              <IconButton
                type="button"
                title="Previous"
                disabled={runtimeActiveItemIndex <= 0}
                onClick={() => {
                  if (runtimeActiveItemIndex > 0)
                    void activateItem(
                      sequence.items[runtimeActiveItemIndex - 1].id,
                    );
                }}
                className="transport-secondary flex h-8 w-8 items-center justify-center rounded-full border-0 bg-transparent p-0 text-text-secondary shadow-none transition-colors hover:translate-y-0 hover:scale-100 hover:text-text-primary disabled:opacity-30"
                aria-label="Previous"
              >
                <SkipBack size={16} fill="currentColor" />
              </IconButton>
              <IconButton
                type="button"
                title={
                  programSongPlayback?.isPlaying ? "Advance" : "Play selection"
                }
                disabled={
                  sequence.items.length === 0 ||
                  (programSongPlayback?.isPlaying === true &&
                    runtimeActiveItemIndex === sequence.items.length - 1 &&
                    sequence.loop === false)
                }
                onClick={() => {
                  if (!programSongPlayback?.isPlaying) {
                    const selection =
                      runtimeActiveItemId ?? sequence.items[0]?.id ?? null;
                    if (selection) void activateItem(selection);
                  } else if (runtimeActiveItemId) {
                    const idx = sequence.items.findIndex(
                      (i) => i.id === runtimeActiveItemId,
                    );
                    if (idx < sequence.items.length - 1)
                      void activateItem(sequence.items[idx + 1].id);
                    else if (sequence.loop !== false)
                      void activateItem(sequence.items[0].id);
                  }
                }}
                className="transport-primary flex h-10 w-10 items-center justify-center rounded-full border-0 bg-sea p-0 text-white shadow-lg transition-transform hover:translate-y-0 hover:scale-105 hover:bg-accent-blue active:scale-95"
                aria-label={
                  programSongPlayback?.isPlaying ? "Advance" : "Play selection"
                }
              >
                <Play size={18} fill="currentColor" className="ml-0.5" />
              </IconButton>
              <IconButton
                type="button"
                title="Stop / Take Off Air"
                onClick={() => void clearActiveItem()}
                className="transport-secondary flex h-8 w-8 items-center justify-center rounded-full border-0 bg-transparent p-0 text-text-secondary shadow-none transition-colors hover:translate-y-0 hover:scale-100 hover:text-text-primary"
                aria-label="Stop / Take Off Air"
              >
                <Square size={16} fill="currentColor" />
              </IconButton>
              <IconButton
                type="button"
                title="Next"
                disabled={
                  runtimeActiveItemIndex < 0 ||
                  runtimeActiveItemIndex >= sequence.items.length - 1
                }
                onClick={() => {
                  if (runtimeActiveItemIndex < sequence.items.length - 1)
                    void activateItem(
                      sequence.items[runtimeActiveItemIndex + 1].id,
                    );
                }}
                className="transport-secondary flex h-8 w-8 items-center justify-center rounded-full border-0 bg-transparent p-0 text-text-secondary shadow-none transition-colors hover:translate-y-0 hover:scale-100 hover:text-text-primary disabled:opacity-30"
                aria-label="Next"
              >
                <SkipForward size={16} fill="currentColor" />
              </IconButton>
            </>
          )}
          {programSongPlayback?.isPlaying &&
          typeof programSongPlayback.telemetryStale === "boolean" ? (
            <div
              className={`flex items-center gap-1 whitespace-nowrap text-[9px] font-semibold uppercase tracking-wider ${programSongPlayback.telemetryStale ? "text-amber-300" : "text-emerald-300"}`}
            >
              <span
                className={`h-1.5 w-1.5 rounded-full ${programSongPlayback.telemetryStale ? "bg-amber-300" : "bg-emerald-300"}`}
                aria-hidden="true"
              />
              Feedback {programSongPlayback.telemetryStale ? "stale" : "live"}
            </div>
          ) : null}
        </div>

        <section
          className="playback-track order-first w-full min-w-0 md:order-none md:w-auto md:flex-1"
          aria-label="On-air player"
        >
          {programSongPlayback?.isPlaying ? (
            (() => {
              const elapsedMs = Math.max(0, programSongPlayback.currentTimeMs);
              const totalMs = programSongPlayback.durationMs;
              const hasTimeline = typeof totalMs === "number" && totalMs > 0;
              const clamped = hasTimeline
                ? Math.min(elapsedMs, totalMs)
                : elapsedMs;
              const ratio = hasTimeline ? clamped / totalMs : 0;
              const fmt = (ms: number) => {
                const seconds = Math.floor(ms / 1000);
                return `${String(Math.floor(seconds / 60)).padStart(2, "0")}:${String(seconds % 60).padStart(2, "0")}`;
              };
              return (
                <div className="playback-track-card relative overflow-hidden rounded-lg border border-sand/30 bg-dark-sand/80">
                  {hasTimeline && (
                    <div
                      className="pointer-events-none absolute inset-0 origin-left bg-sea/20"
                      role="progressbar"
                      aria-label="Track progress"
                      aria-valuenow={Math.round(ratio * 100)}
                      aria-valuemin={0}
                      aria-valuemax={100}
                      style={{
                        transform: `scaleX(${ratio})`,
                        transition: "transform 90ms linear",
                      }}
                    />
                  )}
                  <div className="relative flex items-center gap-2 px-3 py-2">
                    {programSongPlayback.coverUrl ? (
                      <img
                        src={programSongPlayback.coverUrl}
                        alt=""
                        className="h-8 w-8 shrink-0 rounded-sm object-cover"
                      />
                    ) : (
                      <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-sm bg-dark-sand">
                        <Music2 size={11} className="text-text-secondary" />
                      </div>
                    )}
                    <div className="min-w-0 flex-1">
                      <div className="truncate text-xs font-semibold text-sea">
                        {programSongPlayback.title || "Title unavailable"}
                      </div>
                      <div className="truncate text-[10px] text-text-secondary">
                        {programSongPlayback.artist || "Artist unavailable"}
                      </div>
                      {programSongPlayback.introStatus === "degraded" ? (
                        <div className="truncate text-[10px] font-medium text-amber-300">
                          Intro unavailable
                          {programSongPlayback.introFailureReason
                            ? `: ${programSongPlayback.introFailureReason}`
                            : ""}
                        </div>
                      ) : programSongPlayback.introStatus === "playing" ? (
                        <div className="text-[10px] font-medium text-violet-300">
                          Intro playing
                        </div>
                      ) : null}
                    </div>
                    <div className="playback-countdown shrink-0 text-right tabular-nums">
                      <span className="block text-[9px] text-text-secondary">
                        {programSongPlayback.telemetryStale
                          ? "Last reported remaining"
                          : "Remaining"}
                      </span>
                      <strong className="block text-xl leading-tight">
                        {hasTimeline ? fmt(totalMs - clamped) : "—:—"}
                      </strong>
                      <small className="block text-[9px] text-text-secondary">
                        {fmt(clamped)} elapsed
                      </small>
                    </div>
                  </div>
                </div>
              );
            })()
          ) : (
            <p className="px-3 text-[11px] text-text-secondary">
              Nothing on air
            </p>
          )}
        </section>

        <div className="order-1 flex w-full items-center justify-between gap-1 md:order-none md:w-auto md:justify-start md:gap-3">
          {logTransport ? (
            <span
              role="status"
              className="console-status"
              data-tone={logTransport.isRunning ? "ready" : "warning"}
            >
              {logTransport.label}
            </span>
          ) : (
            <>
              <div
                className="flex min-w-0 flex-1 items-center gap-0.5 rounded-lg border border-sand/30 bg-dark-sand/80 p-0.5 md:flex-initial"
                role="group"
                aria-label="Playback mode"
              >
                <Button
                  onClick={() =>
                    applySequence({
                      ...sequence,
                      mode: "manual",
                      activeItemId:
                        runtimeActiveItemId ?? sequence.activeItemId,
                      startedAt: Date.now(),
                    })
                  }
                  aria-pressed={sequence.mode === "manual"}
                  className={`min-w-0 flex-1 rounded-md px-2 py-1 text-[11px] font-semibold transition-colors sm:px-2.5 md:flex-initial ${sequence.mode === "manual" ? "bg-sea text-white ring-1 ring-sea shadow-sm hover:bg-sea" : "bg-transparent text-text-secondary shadow-none hover:text-text-primary"}`}
                  size="sm"
                  variant="secondary"
                >
                  Manual
                </Button>
                <Button
                  onClick={() =>
                    applySequence({
                      ...sequence,
                      mode: "autoplay",
                      activeItemId:
                        runtimeActiveItemId ?? sequence.activeItemId,
                      startedAt: Date.now(),
                    })
                  }
                  aria-pressed={sequence.mode === "autoplay"}
                  className={`flex min-w-0 flex-1 items-center justify-center gap-1 rounded-md px-2 py-1 text-[11px] font-semibold transition-colors sm:px-2.5 md:flex-initial ${sequence.mode === "autoplay" ? "bg-sea text-white ring-1 ring-sea shadow-sm hover:bg-sea" : "bg-transparent text-text-secondary shadow-none hover:text-text-primary"}`}
                  size="sm"
                  variant="secondary"
                >
                  <Play size={9} fill="currentColor" /> Autoplay
                </Button>
                <Button
                  onClick={() => {
                    const shuffled = shuffleProgramSongSequence(
                      sequence,
                      runtimeActiveItemId ?? sequence.activeItemId ?? null,
                    );
                    applySequence(
                      programSongPlayback?.isPlaying
                        ? shuffled
                        : { ...shuffled, startedAt: Date.now() },
                    );
                  }}
                  disabled={sequence.items.length < 2}
                  title={
                    sequence.mode === "shuffle"
                      ? "Shuffle is active; reshuffle playlist"
                      : "Activate shuffle"
                  }
                  aria-label="Shuffle playlist"
                  aria-pressed={sequence.mode === "shuffle"}
                  className={`flex min-w-0 flex-1 items-center justify-center gap-1 rounded-md px-2 py-1 text-[11px] font-semibold transition-colors sm:px-2.5 md:flex-initial ${sequence.mode === "shuffle" ? "bg-sea text-white ring-1 ring-sea shadow-sm hover:bg-sea" : "bg-transparent text-text-secondary shadow-none hover:text-text-primary"} disabled:cursor-not-allowed disabled:opacity-40`}
                  size="sm"
                  variant="secondary"
                >
                  <Shuffle size={9} /> Shuffle
                </Button>
              </div>
              <Button
                type="button"
                title={sequence.loop !== false ? "Loop is on" : "Loop is off"}
                onClick={() =>
                  applySequence({
                    ...sequence,
                    loop: sequence.loop === false ? true : false,
                  })
                }
                className={`flex h-8 items-center justify-center gap-1.5 rounded-lg px-2.5 text-[11px] font-semibold transition-colors ${sequence.loop !== false ? "bg-sea text-white ring-1 ring-sea shadow-sm hover:bg-sea" : "bg-transparent text-text-secondary shadow-none ring-1 ring-sand/30 hover:text-text-primary"}`}
                aria-label={`Loop playlist: ${sequence.loop !== false ? "on" : "off"}`}
                aria-pressed={sequence.loop !== false}
                size="sm"
                variant="secondary"
              >
                <Repeat2 size={14} />
                Loop {sequence.loop !== false ? "on" : "off"}
              </Button>
            </>
          )}
          {onStopAllInstants && (
            <IconButton
              type="button"
              title="Stop All Instants"
              onClick={() => onStopAllInstants()}
              className="flex h-8 w-8 items-center justify-center rounded-full transition-colors text-text-secondary hover:text-terracotta hover:bg-terracotta/10"
              aria-label="Stop All Instants"
            >
              <ZapOff size={16} />
            </IconButton>
          )}
        </div>
      </div>
    </div>
  );
}

import '@testing-library/jest-dom/vitest';

// Node 25 and later define their own global `localStorage`, which is undefined
// unless Node runs with --localstorage-file. Vitest's jsdom environment does not
// overwrite a global that already exists, so on those Node versions
// `window.localStorage` would be Node's empty value instead of jsdom's Storage.
// Use the jsdom window's own storage so the suite behaves the same on every
// supported Node. On Node 22, where no such global exists, this changes nothing.
const jsdomWindow = (globalThis as { jsdom?: { window: Window } }).jsdom?.window;
for (const name of ['localStorage', 'sessionStorage'] as const) {
  if (jsdomWindow && globalThis[name] !== jsdomWindow[name]) {
    Object.defineProperty(globalThis, name, {
      configurable: true,
      value: jsdomWindow[name],
    });
  }
}

import type { ProgramSongQueueEntry } from "../models/broadcast";

const MAX_PROGRAM_SONG_QUEUE_LENGTH = 100;

export function normalizeProgramSongQueue(
  value: unknown,
): ProgramSongQueueEntry[] {
  if (!Array.isArray(value)) return [];
  const ids = new Set<string>();
  const normalized: ProgramSongQueueEntry[] = [];
  for (const candidate of value) {
    if (
      !candidate ||
      typeof candidate !== "object" ||
      Array.isArray(candidate)
    ) {
      continue;
    }
    const record = candidate as Record<string, unknown>;
    const id = typeof record.id === "string" ? record.id.trim() : "";
    const itemId =
      typeof record.itemId === "string" ? record.itemId.trim() : "";
    const enqueuedAt =
      typeof record.enqueuedAt === "number" &&
      Number.isFinite(record.enqueuedAt) &&
      record.enqueuedAt > 0
        ? Math.round(record.enqueuedAt)
        : 0;
    if (!id || !itemId || !enqueuedAt || ids.has(id)) continue;
    ids.add(id);
    normalized.push({ id, itemId, enqueuedAt });
    if (normalized.length >= MAX_PROGRAM_SONG_QUEUE_LENGTH) break;
  }
  return normalized;
}

export type ProgramSequenceMode = 'manual' | 'autoplay' | 'shuffle';
export type ProgramTextContentMode = 'text' | 'sequence';
export type ProgramSongContentMode = 'sequence';

interface BaseSequenceItem {
  id: string;
}

interface BaseSequence<TItem extends BaseSequenceItem> {
  mode: ProgramSequenceMode;
  items: TItem[];
  activeItemId?: string | null;
  intervalMs?: number;
  loop?: boolean;
  startedAt?: number;
}

type RecordValue = Record<string, unknown>;
const MAX_DEPTH = 8;

export interface ProgramTextSequenceLeafItem extends BaseSequenceItem {
  kind: 'preset';
  text: string;
  useMarquee?: boolean;
}

export interface ProgramTextSequenceNestedItem extends BaseSequenceItem {
  label: string;
  kind: 'sequence';
  sequence: ProgramTextSequence;
}

export type ProgramTextSequenceItem =
  | ProgramTextSequenceLeafItem
  | ProgramTextSequenceNestedItem;

export type ProgramTextSequence = BaseSequence<ProgramTextSequenceItem>;

export interface ProgramResolvedTextContent {
  text: string;
  useMarquee: boolean;
  source: ProgramTextContentMode;
  activePathLabels: string[];
}

export interface ProgramResolvedTextLeaf {
  text: string;
  useMarquee: boolean;
  activePathLabels: string[];
}

export interface ProgramSongSequenceLeafItem extends BaseSequenceItem {
  kind: 'preset';
  songId?: number;
  highRotation?: boolean;
  artist: string;
  title: string;
  coverUrl: string;
  audioUrl?: string;
  durationMs?: number;
  earoneSongId?: string;
  earoneRank?: string;
  earoneSpins?: string;
}

export interface ProgramSongSequenceNestedItem extends BaseSequenceItem {
  label: string;
  kind: 'sequence';
  sequence: ProgramSongSequence;
}

export type ProgramSongSequenceItem =
  | ProgramSongSequenceLeafItem
  | ProgramSongSequenceNestedItem;

export type ProgramSongSequence = BaseSequence<ProgramSongSequenceItem>;

export function shuffleProgramSongSequence(
  sequence: ProgramSongSequence,
  activeItemId: string | null = sequence.activeItemId ?? null,
  random: () => number = Math.random
): ProgramSongSequence {
  if (sequence.items.length < 2) return sequence;

  const anchoredItem = activeItemId
    ? sequence.items.find((item) => item.id === activeItemId) ?? null
    : null;
  const shuffledItems = anchoredItem
    ? sequence.items.filter((item) => item.id !== anchoredItem.id)
    : [...sequence.items];

  for (let index = shuffledItems.length - 1; index > 0; index -= 1) {
    const swapIndex = Math.min(index, Math.max(0, Math.floor(random() * (index + 1))));
    [shuffledItems[index], shuffledItems[swapIndex]] = [shuffledItems[swapIndex], shuffledItems[index]];
  }

  const nextItems = anchoredItem ? [anchoredItem, ...shuffledItems] : shuffledItems;
  if (!nextItems.some((item, index) => item.id !== sequence.items[index]?.id) && shuffledItems.length > 1) {
    shuffledItems.push(shuffledItems.shift()!);
  }

  return {
    ...sequence,
    mode: 'shuffle',
    items: anchoredItem ? [anchoredItem, ...shuffledItems] : shuffledItems,
    activeItemId: anchoredItem?.id ?? sequence.activeItemId ?? nextItems[0]?.id ?? null
  };
}

export interface ProgramResolvedSongLeaf {
  id: string;
  songId?: number;
  highRotation: boolean;
  artist: string;
  title: string;
  coverUrl: string;
  audioUrl?: string;
  durationMs?: number;
  earoneSongId?: string;
  earoneRank?: string;
  earoneSpins?: string;
  activePathLabels: string[];
}

function asRecord(value: unknown): RecordValue | null {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    return null;
  }
  return value as RecordValue;
}

function createId(prefix: string): string {
  return `${prefix}_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`;
}

function normalizeMode(value: unknown): ProgramSequenceMode {
  if (value === 'autoplay') return 'autoplay';
  if (value === 'shuffle') return 'shuffle';
  return 'manual';
}

function normalizeTextContentMode(
  contentMode: unknown,
  sequence: ProgramTextSequence | null
): ProgramTextContentMode {
  if (contentMode === 'text') {
    return 'text';
  }
  if (contentMode === 'sequence') {
    return 'sequence';
  }
  return sequence ? 'sequence' : 'text';
}

function normalizeSongContentMode(
  contentMode: unknown,
  sequence: ProgramSongSequence | null
): ProgramSongContentMode {
  return 'sequence';
}

function normalizeTextLeafItem(
  record: RecordValue,
  options?: { includeMarquee?: boolean }
): ProgramTextSequenceLeafItem {
  const text =
    typeof record.text === 'string' && record.text.trim()
      ? record.text
      : typeof record.label === 'string'
        ? record.label
        : '';

  return {
    id: typeof record.id === 'string' && record.id ? record.id : createId('preset'),
    kind: 'preset',
    text,
    useMarquee: options?.includeMarquee ? Boolean(record.useMarquee) : undefined
  };
}

function normalizeSongLeafItem(record: RecordValue): ProgramSongSequenceLeafItem {
  const artist =
    typeof record.artist === 'string' && record.artist.trim()
      ? record.artist.trim()
      : '';
  const title =
    typeof record.title === 'string' && record.title.trim()
      ? record.title.trim()
      : '';
  const coverUrl =
    typeof record.coverUrl === 'string' && record.coverUrl.trim()
      ? record.coverUrl.trim()
      : '';
  const audioUrl =
    typeof record.audioUrl === 'string' && record.audioUrl.trim()
      ? record.audioUrl.trim()
      : '';
  const durationMs =
    typeof record.durationMs === 'number' &&
    Number.isFinite(record.durationMs) &&
    record.durationMs > 0
      ? Math.round(record.durationMs)
      : undefined;

  return {
    id: typeof record.id === 'string' && record.id ? record.id : createId('song'),
    kind: 'preset',
    songId:
      typeof record.songId === 'number' && Number.isInteger(record.songId) && record.songId > 0
        ? record.songId
        : undefined,
    highRotation: record.highRotation === true,
    artist,
    title,
    coverUrl,
    audioUrl: audioUrl || undefined,
    durationMs,
    earoneSongId:
      typeof record.earoneSongId === 'string' && record.earoneSongId.trim()
        ? record.earoneSongId.trim()
        : typeof record.earoneSongId === 'number' && Number.isFinite(record.earoneSongId)
          ? String(record.earoneSongId)
          : undefined,
    earoneRank:
      typeof record.earoneRank === 'string' && record.earoneRank.trim()
        ? record.earoneRank.trim()
        : undefined,
    earoneSpins:
      typeof record.earoneSpins === 'string' && record.earoneSpins.trim()
        ? record.earoneSpins.trim()
        : typeof record.earoneSpins === 'number' && Number.isFinite(record.earoneSpins)
          ? String(record.earoneSpins)
          : undefined
  };
}

function withNormalizedSequenceShape<TItem extends BaseSequenceItem>(
  record: RecordValue,
  items: TItem[],
  defaultMode: ProgramSequenceMode = 'manual'
): BaseSequence<TItem> {
  const activeItemId =
    record.activeItemId === null
      ? null
      : typeof record.activeItemId === 'string' && items.some((item) => item.id === record.activeItemId)
      ? record.activeItemId
      : items[0]?.id ?? null;

  return {
    mode: record.mode === undefined ? defaultMode : normalizeMode(record.mode),
    items,
    activeItemId,
    intervalMs:
      typeof record.intervalMs === 'number' && Number.isFinite(record.intervalMs) && record.intervalMs >= 500
        ? Math.floor(record.intervalMs)
        : 4000,
    loop: record.loop === undefined ? true : Boolean(record.loop),
    startedAt:
      typeof record.startedAt === 'number' && Number.isFinite(record.startedAt)
        ? record.startedAt
        : Date.now()
  };
}

function normalizeTextSequenceItem(
  value: unknown,
  depth: number,
  options?: { includeMarquee?: boolean }
): ProgramTextSequenceItem | null {
  const record = asRecord(value);
  if (!record) {
    return null;
  }

  if (record.kind === 'sequence') {
    const normalizedSequence = normalizeProgramTextSequence(record.sequence, depth + 1, options);
    if (!normalizedSequence) {
      return null;
    }

    return {
      id: typeof record.id === 'string' && record.id ? record.id : createId('sequence'),
      label: typeof record.label === 'string' && record.label.trim() ? record.label : 'Nested Sequence',
      kind: 'sequence',
      sequence: normalizedSequence
    };
  }

  return normalizeTextLeafItem(record, options);
}

function normalizeSongSequenceItem(
  value: unknown,
  depth: number
): ProgramSongSequenceItem | null {
  const record = asRecord(value);
  if (!record) {
    return null;
  }

  if (record.kind === 'sequence') {
    const normalizedSequence = normalizeProgramSongSequence(record.sequence, depth + 1);
    if (!normalizedSequence) {
      return null;
    }

    return {
      id: typeof record.id === 'string' && record.id ? record.id : createId('sequence'),
      label: typeof record.label === 'string' && record.label.trim() ? record.label : 'Nested Sequence',
      kind: 'sequence',
      sequence: normalizedSequence
    };
  }

  return normalizeSongLeafItem(record);
}

function getBaseIndex<TItem extends BaseSequenceItem>(
  sequence: BaseSequence<TItem>
): number | null {
  if (sequence.activeItemId === null) {
    return null;
  }

  const activeIndex = sequence.items.findIndex((item) => item.id === sequence.activeItemId);
  return activeIndex >= 0 ? activeIndex : 0;
}

function getSelectedItem<TItem extends BaseSequenceItem>(
  sequence: BaseSequence<TItem>,
  nowMs: number
): TItem | null {
  if (sequence.items.length === 0) {
    return null;
  }

  const baseIndex = getBaseIndex(sequence);
  if (baseIndex === null) {
    return null;
  }

  if (sequence.mode === 'manual') {
    return sequence.items[baseIndex] ?? null;
  }

  const startedAt = sequence.startedAt ?? nowMs;
  const intervalMs = Math.max(500, sequence.intervalMs ?? 4000);
  const elapsedSteps = Math.max(0, Math.floor((nowMs - startedAt) / intervalMs));
  let nextIndex = baseIndex + elapsedSteps;

  if (sequence.loop !== false) {
    nextIndex %= sequence.items.length;
  } else if (nextIndex >= sequence.items.length) {
    nextIndex = sequence.items.length - 1;
  }

  return sequence.items[nextIndex] ?? null;
}

function getSongItemPlaybackDurationMs(
  item: ProgramSongSequenceItem
): number | null {
  if (
    item.kind === 'preset' &&
    typeof item.durationMs === 'number' &&
    Number.isFinite(item.durationMs) &&
    item.durationMs > 0
  ) {
    return Math.max(1, Math.round(item.durationMs));
  }

  return null;
}

function getSelectedSongItem(
  sequence: ProgramSongSequence,
  nowMs: number
): ProgramSongSequenceItem | null {
  if (sequence.items.length === 0) {
    return null;
  }

  const baseIndex = getBaseIndex(sequence);
  if (baseIndex === null) {
    return null;
  }

  if (sequence.mode === 'manual') {
    return sequence.items[baseIndex] ?? null;
  }

  const startedAt = sequence.startedAt ?? nowMs;
  const elapsedMs = Math.max(0, nowMs - startedAt);
  const itemDurations = sequence.items.map((item) => getSongItemPlaybackDurationMs(item));

  if (sequence.loop !== false) {
    const hasUnknownDuration = itemDurations.some((durationMs) => durationMs === null);
    if (!hasUnknownDuration) {
      const cycleDurationMs = itemDurations.reduce<number>((sum, durationMs) => sum + (durationMs ?? 0), 0);
      if (cycleDurationMs <= 0) {
        return sequence.items[baseIndex] ?? null;
      }

      let remainingMs = elapsedMs % cycleDurationMs;
      for (let step = 0; step < sequence.items.length; step += 1) {
        const index = (baseIndex + step) % sequence.items.length;
        const itemDurationMs = itemDurations[index];
        if (typeof itemDurationMs !== 'number') {
          return sequence.items[index] ?? null;
        }
        if (remainingMs < itemDurationMs) {
          return sequence.items[index] ?? null;
        }
        remainingMs -= itemDurationMs;
      }

      return sequence.items[baseIndex] ?? null;
    }

    let remainingMs = elapsedMs;
    for (let step = 0; step < sequence.items.length; step += 1) {
      const index = (baseIndex + step) % sequence.items.length;
      const itemDurationMs = itemDurations[index];
      if (typeof itemDurationMs !== 'number') {
        return sequence.items[index] ?? null;
      }
      if (remainingMs < itemDurationMs) {
        return sequence.items[index] ?? null;
      }
      remainingMs -= itemDurationMs;
    }

    return sequence.items[baseIndex] ?? null;
  }

  let index = baseIndex;
  let remainingMs = elapsedMs;
  while (index < sequence.items.length - 1) {
    const itemDurationMs = itemDurations[index];
    if (typeof itemDurationMs !== 'number') {
      return sequence.items[index] ?? null;
    }
    if (remainingMs < itemDurationMs) {
      break;
    }
    remainingMs -= itemDurationMs;
    index += 1;
  }

  return sequence.items[index] ?? null;
}

function resolveTextSequenceRecursive(
  sequence: ProgramTextSequence,
  nowMs: number,
  depth: number,
  labels: string[]
): ProgramResolvedTextLeaf | null {
  if (depth > MAX_DEPTH) {
    return null;
  }

  const selected = getSelectedItem(sequence, nowMs);
  if (!selected) {
    return null;
  }

  if (selected.kind === 'sequence') {
    const nextLabels = [...labels, selected.label];
    return resolveTextSequenceRecursive(selected.sequence, nowMs, depth + 1, nextLabels);
  }

  return {
    text: selected.text,
    useMarquee: Boolean(selected.useMarquee),
    activePathLabels: [...labels, selected.text]
  };
}

function resolveSongSequenceRecursive(
  sequence: ProgramSongSequence,
  nowMs: number,
  depth: number,
  labels: string[]
): ProgramResolvedSongLeaf | null {
  if (depth > MAX_DEPTH) {
    return null;
  }

  const selected = getSelectedSongItem(sequence, nowMs);
  if (!selected) {
    return null;
  }

  if (selected.kind === 'sequence') {
    const nextLabels = [...labels, selected.label];
    return resolveSongSequenceRecursive(selected.sequence, nowMs, depth + 1, nextLabels);
  }

  const songLabel = [selected.artist, selected.title].filter(Boolean).join(' - ');
  return {
    id: selected.id,
    songId: selected.songId,
    highRotation: selected.highRotation === true,
    artist: selected.artist,
    title: selected.title,
    coverUrl: selected.coverUrl,
    audioUrl: selected.audioUrl,
    durationMs: selected.durationMs,
    earoneSongId: selected.earoneSongId,
    earoneRank: selected.earoneRank,
    earoneSpins: selected.earoneSpins,
    activePathLabels: [...labels, songLabel || 'Song Preset']
  };
}

export function normalizeProgramTextSequence(
  value: unknown,
  depth = 0,
  options?: { includeMarquee?: boolean }
): ProgramTextSequence | null {
  if (depth > MAX_DEPTH) {
    return null;
  }

  const record = asRecord(value);
  if (!record) {
    return null;
  }

  const rawItems = Array.isArray(record.items) ? record.items : [];
  const items = rawItems
    .map((item) => normalizeTextSequenceItem(item, depth, options))
    .filter((item): item is ProgramTextSequenceItem => item !== null);

  return withNormalizedSequenceShape(record, items);
}

export function normalizeProgramSongSequence(
  value: unknown,
  depth = 0
): ProgramSongSequence | null {
  if (depth > MAX_DEPTH) {
    return null;
  }

  const record = asRecord(value);
  if (!record) {
    return null;
  }

  const rawItems = Array.isArray(record.items) ? record.items : [];
  const items = rawItems
    .map((item) => normalizeSongSequenceItem(item, depth))
    .filter((item): item is ProgramSongSequenceItem => item !== null);

  return withNormalizedSequenceShape(record, items, 'autoplay');
}

export function createProgramTextSequenceItem(
  kind: ProgramTextSequenceItem['kind'] = 'preset',
  options?: { includeMarquee?: boolean }
): ProgramTextSequenceItem {
  if (kind === 'sequence') {
    return {
      id: createId('sequence'),
      label: 'Nested Sequence',
      kind: 'sequence',
      sequence: createProgramTextSequence('manual', options)
    };
  }

  return {
    id: createId('preset'),
    kind: 'preset',
    text: '',
    useMarquee: options?.includeMarquee ? false : undefined
  };
}

export function createProgramSongSequenceItem(
  kind: ProgramSongSequenceItem['kind'] = 'preset'
): ProgramSongSequenceItem {
  if (kind === 'sequence') {
    return {
      id: createId('sequence'),
      label: 'Nested Sequence',
      kind: 'sequence',
      sequence: createProgramSongSequence('manual')
    };
  }

  return {
    id: createId('song'),
    kind: 'preset',
    highRotation: false,
    artist: '',
    title: '',
    coverUrl: '',
    audioUrl: '',
    durationMs: undefined
  };
}

export function createProgramTextSequence(
  mode: ProgramSequenceMode = 'manual',
  options?: { includeMarquee?: boolean }
): ProgramTextSequence {
  const firstItem = createProgramTextSequenceItem('preset', options);

  return {
    mode,
    items: [firstItem],
    activeItemId: firstItem.id,
    intervalMs: 4000,
    loop: true,
    startedAt: Date.now()
  };
}

export function createProgramSongSequence(
  mode: ProgramSequenceMode = 'autoplay'
): ProgramSongSequence {
  return {
    mode,
    items: [],
    activeItemId: null,
    intervalMs: 4000,
    loop: true,
    startedAt: Date.now()
  };
}

export function getProgramTextContentMode(
  contentMode: unknown,
  sequence: ProgramTextSequence | null
): ProgramTextContentMode {
  return normalizeTextContentMode(contentMode, sequence);
}

export function getProgramSongContentMode(
  contentMode: unknown,
  sequence: ProgramSongSequence | null
): ProgramSongContentMode {
  return normalizeSongContentMode(contentMode, sequence);
}

export function getProgramTextSequenceSelectedItemId(
  sequence: ProgramTextSequence,
  nowMs = Date.now()
): string | null {
  return getSelectedItem(sequence, nowMs)?.id ?? null;
}

export function getProgramSongSequenceSelectedItemId(
  sequence: ProgramSongSequence,
  nowMs = Date.now()
): string | null {
  return getSelectedSongItem(sequence, nowMs)?.id ?? null;
}

export function resolveProgramTextContent(
  config: {
    text?: string;
    useMarquee?: boolean;
    contentMode?: unknown;
    sequence?: unknown;
  },
  nowMs = Date.now(),
  options?: { includeMarquee?: boolean }
): ProgramResolvedTextContent {
  const normalizedSequence = normalizeProgramTextSequence(config.sequence, 0, options);
  const contentMode = normalizeTextContentMode(config.contentMode, normalizedSequence);

  if (contentMode === 'sequence' && normalizedSequence) {
    const resolved = resolveTextSequenceRecursive(normalizedSequence, nowMs, 0, []);
    if (resolved) {
      return {
        text: resolved.text,
        useMarquee: resolved.useMarquee,
        source: 'sequence',
        activePathLabels: resolved.activePathLabels
      };
    }
  }

  return {
    text: typeof config.text === 'string' ? config.text : '',
    useMarquee: Boolean(config.useMarquee),
    source: 'text',
    activePathLabels: []
  };
}

export function resolveProgramTextLeaf(
  config: {
    contentMode?: unknown;
    sequence?: unknown;
  },
  nowMs = Date.now(),
  options?: { includeMarquee?: boolean }
): ProgramResolvedTextLeaf | null {
  const normalizedSequence = normalizeProgramTextSequence(config.sequence, 0, options);
  const contentMode = normalizeTextContentMode(config.contentMode, normalizedSequence);

  if (contentMode !== 'sequence' || !normalizedSequence) {
    return null;
  }

  return resolveTextSequenceRecursive(normalizedSequence, nowMs, 0, []);
}

export function resolveProgramSongLeaf(
  config: {
    contentMode?: unknown;
    sequence?: unknown;
  },
  nowMs = Date.now()
): ProgramResolvedSongLeaf | null {
  const normalizedSequence = normalizeProgramSongSequence(config.sequence);
  const contentMode = normalizeSongContentMode(config.contentMode, normalizedSequence);

  if (contentMode !== 'sequence' || !normalizedSequence) {
    return null;
  }

  return resolveSongSequenceRecursive(normalizedSequence, nowMs, 0, []);
}

export function countProgramTextSequenceLeafItems(
  sequence: ProgramTextSequence | null
): number {
  if (!sequence) {
    return 0;
  }

  return sequence.items.reduce((count, item) => {
    if (item.kind === 'sequence') {
      return count + countProgramTextSequenceLeafItems(item.sequence);
    }
    return count + 1;
  }, 0);
}

export function countProgramSongSequenceLeafItems(
  sequence: ProgramSongSequence | null
): number {
  if (!sequence) {
    return 0;
  }

  return sequence.items.reduce((count, item) => {
    if (item.kind === 'sequence') {
      return count + countProgramSongSequenceLeafItems(item.sequence);
    }
    return count + 1;
  }, 0);
}

