// Node 25 and later define their own global `localStorage`, which is undefined
// unless Node runs with --localstorage-file. Vitest's jsdom environment does not
// overwrite a global that already exists, so on those Node versions
// `window.localStorage` would be Node's empty value instead of jsdom's Storage.
// Use the jsdom window's own storage so the suite behaves the same on every
// supported Node. On Node 22, where no such global exists, this changes nothing.
const jsdomWindow = (globalThis as { jsdom?: { window: Window } }).jsdom?.window;
for (const name of ['localStorage', 'sessionStorage'] as const) {
  if (jsdomWindow && globalThis[name] !== jsdomWindow[name]) {
    Object.defineProperty(globalThis, name, {
      configurable: true,
      value: jsdomWindow[name],
    });
  }
}

import type { ProgramSongQueueEntry } from "../models/broadcast";

const MAX_PROGRAM_SONG_QUEUE_LENGTH = 100;

export function normalizeProgramSongQueue(
  value: unknown,
): ProgramSongQueueEntry[] {
  if (!Array.isArray(value)) return [];
  const ids = new Set<string>();
  const normalized: ProgramSongQueueEntry[] = [];
  for (const candidate of value) {
    if (
      !candidate ||
      typeof candidate !== "object" ||
      Array.isArray(candidate)
    ) {
      continue;
    }
    const record = candidate as Record<string, unknown>;
    const id = typeof record.id === "string" ? record.id.trim() : "";
    const itemId =
      typeof record.itemId === "string" ? record.itemId.trim() : "";
    const enqueuedAt =
      typeof record.enqueuedAt === "number" &&
      Number.isFinite(record.enqueuedAt) &&
      record.enqueuedAt > 0
        ? Math.round(record.enqueuedAt)
        : 0;
    if (!id || !itemId || !enqueuedAt || ids.has(id)) continue;
    ids.add(id);
    normalized.push({ id, itemId, enqueuedAt });
    if (normalized.length >= MAX_PROGRAM_SONG_QUEUE_LENGTH) break;
  }
  return normalized;
}

